// Copyright 2026. Fog of War chess engine.
//
// A learned prior over the opponent's moves, used by the particle filter to
// weight each hypothesis' successors. Replaces the three hand-set constants of
// v5 with a conditional-logit model fitted on the recorded decisions of the
// strongest arena players (learning/opponent_model.py); the weights live in
// opponent_weights.h, generated by that script. The features are a handful of
// attack and visibility tests per move, because the prior runs for every
// successor of every particle.
//
// learning/tests/test_opponent_parity.py checks these features against the
// Python ones over real positions.

#ifndef FOW_OPPONENT_MODEL_H_
#define FOW_OPPONENT_MODEL_H_

#include "move.h"
#include "position.h"

namespace fow {

inline constexpr int kNumOpponentFeatures = 26;

// Fills `out` with the features of `move` for the side to move on `board`,
// which is the full (hypothesis) board. `last_to` is the destination of that
// player's previous move in this hypothesis (-1 if unknown) and
// `last_capture` whether it captured; both come from the particle's memory.
// `board` is left unchanged.
void OpponentMoveFeatures(Position* board, Move move, int last_to,
                          bool last_capture, double out[kNumOpponentFeatures]);

// exp(w . f): the unnormalised plausibility of `move`.
double LearnedMovePlausibility(Position* board, Move move, int last_to,
                               bool last_capture);

}  // namespace fow

#endif  // FOW_OPPONENT_MODEL_H_
